content.content:
1	//! Browser notification support for new chat messages.
2	//!
3	//! Sends desktop notifications when:
4	//! - Document is not visible (tab hidden or window not focused)
5	//! - Message is from another user (not self)
6	//! - Room is not currently active
7	//! - Permission has been granted
8	
9	use crate::components::app::{CURRENT_ROOM, ROOMS};
10	use crate::room_data::CurrentRoom;
11	use crate::util::ecies::{decrypt_with_symmetric_key, unseal_bytes_with_secrets};
12	use dioxus::logger::tracing::{debug, info, warn};
13	use dioxus::prelude::*;
14	use ed25519_dalek::VerifyingKey;
15	use river_core::room_state::member::MemberId;
16	use river_core::room_state::member_info::MemberInfoV1;
17	use river_core::room_state::message::{AuthorizedMessageV1, RoomMessageBody};
18	use std::collections::HashSet;
19	#[cfg(target_arch = "wasm32")]
20	use wasm_bindgen::prelude::*;
21	#[cfg(target_arch = "wasm32")]
22	use wasm_bindgen_futures::JsFuture;
23	#[cfg(target_arch = "wasm32")]
24	use web_sys::{Notification, NotificationOptions, VisibilityState};
25	// `NotificationPermission` is a plain web-sys enum (no JS calls), so it
26	// resolves on every target and can stay in shared signatures.
27	use web_sys::NotificationPermission;
28	
29	#[cfg(target_arch = "wasm32")]
30	const NOTIFICATION_PROMPTED_KEY: &str = "river_notification_prompted";
31	
32	/// Test function to verify browser notifications work at all.
33	/// Can be called from browser console via: river_test_notification()
34	#[cfg(target_arch = "wasm32")]
35	#[wasm_bindgen]
36	pub fn river_test_notification() {
37	    web_sys::console::log_1(&wasm_bindgen::JsValue::from_str(
38	        "[River] Testing notification system...",
39	    ));
40	
41	    let permission = get_permission();
42	    web_sys::console::log_1(&wasm_bindgen::JsValue::from_str(&format!(
43	        "[River] Current permission: {:?}",
44	        permission
45	    )));
46	
47	    if permission == NotificationPermission::Granted {
48	        let options = NotificationOptions::new();
49	        options.set_body("If you see this, notifications are working!");
50	
51	        match Notification::new_with_options("River Test Notification", &options) {
52	            Ok(_notification) => {
53	                web_sys::console::log_1(&wasm_bindgen::JsValue::from_str(
54	                    "[River] Test notification created successfully! You should see it now.",
55	                ));
56	            }
57	            Err(e) => {
58	                web_sys::console::error_1(&wasm_bindgen::JsValue::from_str(&format!(
59	                    "[River] Failed to create test notification: {:?}",
60	                    e
61	                )));
62	            }
63	        }
64	    } else if permission == NotificationPermission::Default {
65	        web_sys::console::log_1(&wasm_bindgen::JsValue::from_str(
66	            "[River] Permission not yet granted. Requesting permission...",
67	        ));
68	        wasm_bindgen_futures::spawn_local(async {
69	            let granted = request_permission().await;
70	            if granted {
71	                web_sys::console::log_1(&wasm_bindgen::JsValue::from_str(
72	                    "[River] Permission granted! Run riverTestNotification() again to test.",
73	                ));
74	            } else {
75	                web_sys::console::log_1(&wasm_bindgen::JsValue::from_str(
76	                    "[River] Permission denied or dismissed.",
77	                ));
78	            }
79	        });
80	    } else {
81	        web_sys::console::log_1(&wasm_bindgen::JsValue::from_str(
82	            "[River] Notifications are denied. Please enable them in browser settings.",
83	        ));
84	    }
85	}
86	
87	/// Tracks which rooms have completed initial sync (don't notify for initial message load)
88	pub static INITIAL_SYNC_COMPLETE: GlobalSignal<HashSet<VerifyingKey>> = Global::new(HashSet::new);
89	
90	/// Check if the document is currently visible and focused
91	#[cfg(target_arch = "wasm32")]
92	pub fn is_document_visible() -> bool {
93	    if let Some(window) = crate::platform::window() {
94	        if let Some(document) = window.document() {
95	            let is_visible = document.visibility_state() == VisibilityState::Visible;
96	            let has_focus = document.has_focus().unwrap_or(false);
97	            return is_visible && has_focus;
98	        }
99	    }
100	    // Default to visible to avoid spurious notifications
101	    true
102	}
103	
104	/// Native (mobile/desktop) builds have no document visibility concept here;
105	/// treat the app as always visible so the notify path simply suppresses
106	/// notifications for the current room (see `notify_new_messages`).
107	#[cfg(not(target_arch = "wasm32"))]
108	pub fn is_document_visible() -> bool {
109	    true
110	}
111	
112	/// Get current notification permission status
113	#[cfg(target_arch = "wasm32")]
114	pub fn get_permission() -> NotificationPermission {
115	    Notification::permission()
116	}
117	
118	/// Native builds expose no browser Notification API. Report `Denied` so all
119	/// callers short-circuit before touching any web-only code path.
120	#[cfg(not(target_arch = "wasm32"))]
121	pub fn get_permission() -> NotificationPermission {
122	    NotificationPermission::Denied
123	}
124	
125	/// Request notification permission from the user
126	/// Returns true if permission was granted
127	#[cfg(target_arch = "wasm32")]
128	pub async fn request_permission() -> bool {
129	    match Notification::request_permission() {
130	        Ok(promise) => match JsFuture::from(promise).await {
131	            Ok(result) => {
132	                let permission_str = result.as_string().unwrap_or_default();
133	                info!("Notification permission result: {}", permission_str);
134	                permission_str == "granted"
135	            }
136	            Err(e) => {
137	                warn!("Failed to request notification permission: {:?}", e);
138	                false
139	            }
140	        },
141	        Err(e) => {
142	            warn!("Failed to request notification permission: {:?}", e);
143	            false
144	        }
145	    }
146	}
147	
148	/// Check if we've already prompted the user for notification permission
149	#[cfg(target_arch = "wasm32")]
150	fn has_prompted_for_permission() -> bool {
151	    if let Some(window) = crate::platform::window() {
152	        if let Ok(Some(storage)) = window.local_storage() {
153	            return storage
154	                .get_item(NOTIFICATION_PROMPTED_KEY)
155	                .ok()
156	                .flatten()
157	                .is_some();
158	        }
159	    }
160	    false
161	}
162	
163	/// Mark that we've prompted the user for notification permission
164	#[cfg(target_arch = "wasm32")]
165	fn mark_prompted_for_permission() {
166	    if let Some(window) = crate::platform::window() {
167	        if let Ok(Some(storage)) = window.local_storage() {
168	            let _ = storage.set_item(NOTIFICATION_PROMPTED_KEY, "true");
169	        }
170	    }
171	}
172	
173	/// Request notification permission on first user message.
174	///
175	/// This follows best practices:
176	/// - Only prompts once per browser (persisted in localStorage)
177	/// - Respects if user already granted or denied permission
178	/// - Triggered by user action (sending a message) for better UX
179	#[cfg(target_arch = "wasm32")]
180	pub fn request_permission_on_first_message() {
181	    let permission = get_permission();
182	
183	    // Already have a definitive answer - don't prompt
184	    if permission == NotificationPermission::Granted {
185	        debug!("Notification permission already granted");
186	        return;
187	    }
188	
189	    if permission == NotificationPermission::Denied {
190	        debug!("Notification permission already denied");
191	        return;
192	    }
193	
194	    // Permission is "default" (not yet asked) - check if we've prompted before
195	    if has_prompted_for_permission() {
196	        debug!("Already prompted for notification permission previously");
197	        return;
198	    }
199	
200	    // First time - request permission
201	    info!("Requesting notification permission on first message");
202	    mark_prompted_for_permission();
203	
204	    crate::util::safe_spawn_local(async {
205	        let granted = request_permission().await;
206	        if granted {
207	            info!("User granted notification permission");
208	        } else {
209	            info!("User did not grant notification permission");
210	        }
211	    });
212	}
213	
214	/// Show a notification for new messages in a room
215	///
216	/// # Arguments
217	/// * `room_key` - The room's owner verifying key
218	/// * `room_name` - Display name of the room
219	/// * `sender_name` - Name of the message sender
220	/// * `message_preview` - Truncated message content
221	#[cfg(target_arch = "wasm32")]
222	pub fn show_notification(
223	    room_key: VerifyingKey,
224	    room_name: &str,
225	    sender_name: &str,
226	    message_preview: &str,
227	) {
228	    // Check permission
229	    let permission = get_permission();
230	    info!(
231	        "show_notification called for room '{}', permission: {:?}",
232	        room_name, permission
233	    );
234	
235	    if permission == NotificationPermission::Denied {
236	        info!("Notifications denied by browser, skipping");
237	        return;
238	    }
239	
240	    // If permission is default (not yet asked), request it first
241	    if permission == NotificationPermission::Default {
242	        let room_name = room_name.to_string();
243	        let sender_name = sender_name.to_string();
244	        let message_preview = message_preview.to_string();
245	        wasm_bindgen_futures::spawn_local(async move {
246	            let granted = request_permission().await;
247	            if granted {
248	                // Try again after permission granted
249	                create_notification_internal(room_key, &room_name, &sender_name, &message_preview);
250	            }
251	        });
252	        return;
253	    }
254	
255	    // Permission is granted, show notification
256	    create_notification_internal(room_key, room_name, sender_name, message_preview);
257	}
258	
259	/// Native stub — desktop/mobile notifications would require an OS-level
260	/// integration (JNI on Android); not wired up yet, so this is a no-op.
261	#[cfg(not(target_arch = "wasm32"))]
262	pub fn show_notification(
263	    _room_key: VerifyingKey,
264	    _room_name: &str,
265	    _sender_name: &str,
266	    _message_preview: &str,
267	) {
268	}
269	
270	#[cfg(target_arch = "wasm32")]
271	fn create_notification_internal(
272	    room_key: VerifyingKey,
273	    room_name: &str,
274	    sender_name: &str,
275	    message_preview: &str,
276	) {
277	    let body = format!("{}: {}", sender_name, message_preview);
278	    info!(
279	        "Creating notification - title: '{}', body: '{}'",
280	        room_name, body
281	    );
282	
283	    // Log to browser console for debugging
284	    let console_msg = format!("[River] Creating notification: {} - {}", room_name, body);
285	    web_sys::console::log_1(&wasm_bindgen::JsValue::from_str(&console_msg));
286	
287	    let options = NotificationOptions::new();
288	    options.set_body(&body);
289	    // Could add icon here: options.icon("/assets/river_logo.svg");
290	
291	    match Notification::new_with_options(room_name, &options) {
292	        Ok(notification) => {
293	            // Log to browser console for confirmation
294	            web_sys::console::log_1(&wasm_bindgen::JsValue::from_str(
295	                "[River] Notification object created successfully",
296	            ));
297	
298	            // Set up click handler to focus window and switch to room
299	            let onclick = Closure::wrap(Box::new(move || {
300	                info!("Notification clicked, switching to room");
301	
302	                // Switch to the room
303	                *CURRENT_ROOM.write() = CurrentRoom {
304	                    owner_key: Some(room_key),
305	                };
306	
307	                // Focus the window
308	                if let Some(window) = crate::platform::window() {
309	                    let _ = window.focus();
310	                }
311	            }) as Box<dyn Fn()>);
312	
313	            notification.set_onclick(Some(onclick.as_ref().unchecked_ref()));
314	
315	            // Prevent the closure from being dropped
316	            onclick.forget();
317	
318	            info!(
319	                "Notification created for room: {} (check browser console)",
320	                room_name
321	            );
322	        }
323	        Err(e) => {
324	            warn!("Failed to create notification: {:?}", e);
325	            // Also log to console
326	            let err_msg = format!("[River] FAILED to create notification: {:?}", e);
327	            web_sys::console::error_1(&wasm_bindgen::JsValue::from_str(&err_msg));
328	        }
329	    }
330	}
331	
332	/// Process new messages and show notifications if appropriate
333	/// Called from apply_delta when new messages are received
334	///
335	/// # Arguments
336	/// * `room_key` - The room's owner verifying key
337	/// * `new_messages` - New messages from the delta
338	/// * `self_member_id` - The current user's member ID (to filter out own messages)
339	/// * `member_info` - Member info for looking up sender names
340	/// * `room_secrets` - Map of secret_version -> decrypted secret for version-aware decryption
341	pub fn notify_new_messages(
342	    room_key: &VerifyingKey,
343	    new_messages: &[AuthorizedMessageV1],
344	    self_member_id: MemberId,
345	    member_info: &MemberInfoV1,
346	    room_secrets: &std::collections::HashMap<u32, [u8; 32]>,
347	) {
348	    // Skip if this room hasn't completed initial sync
349	    if !INITIAL_SYNC_COMPLETE.read().contains(room_key) {
350	        info!(
351	            "Initial sync not complete for room {:?}, skipping notification",
352	            MemberId::from(*room_key)
353	        );
354	        return;
355	    }
356	    info!(
357	        "notify_new_messages called for room {:?} with {} messages",
358	        MemberId::from(*room_key),
359	        new_messages.len()
360	    );
361	
362	    // Skip if this is the currently active room AND document is visible
363	    // (user is looking at this room right now)
364	    let doc_visible = is_document_visible();
365	    if doc_visible {
366	        if let Some(current_key) = CURRENT_ROOM.read().owner_key {
367	            if current_key == *room_key {
368	                info!(
369	                    "Room {:?} is currently active and visible, skipping notification",
370	                    MemberId::from(*room_key)
371	                );
372	                return;
373	            }
374	        }
375	    }
376	    info!(
377	        "Document visible: {}, proceeding with notification check",
378	        doc_visible
379	    );
380	
381	    // Skip if document is visible and focused AND we're in a different room
382	    // This prevents notifications while actively using River, but allows them
383	    // when the app is in background (minimized, different tab, etc.)
384	    // Note: We still notify for other rooms because users want to know about
385	    // activity in other conversations even while using the app.
386	    // Uncomment this block to suppress ALL notifications while app is focused:
387	    // if is_document_visible() {
388	    //     debug!("Document visible, skipping notification");
389	    //     return;
390	    // }
391	
392	    // Filter to messages from other users
393	    let external_messages: Vec<_> = new_messages
394	        .iter()
395	        .filter(|msg| msg.message.author != self_member_id)
396	        .collect();
397	
398	    info!(
399	        "Filtered to {} external messages (from {} total, self_member_id: {:?})",
400	        external_messages.len(),
401	        new_messages.len(),
402	        self_member_id
403	    );
404	
405	    if external_messages.is_empty() {
406	        info!("No external messages to notify about");
407	        return;
408	    }
409	
410	    // Get room name (decrypt if private)
411	    let room_name = ROOMS
412	        .read()
413	        .map
414	        .get(room_key)
415	        .map(|rd| {
416	            let sealed_name = &rd.room_state.configuration.configuration.display.name;
417	            match unseal_bytes_with_secrets(sealed_name, room_secrets) {
418	                Ok(bytes) => String::from_utf8_lossy(&bytes).to_string(),
419	                Err(_) => sealed_name.to_string_lossy(),
420	            }
421	        })
422	        .unwrap_or_else(|| "Room".to_string());
423	
424	    // For multiple messages, show a summary
425	    if external_messages.len() > 1 {
426	        show_notification(
427	            *room_key,
428	            &room_name,
429	            "",
430	            &format!("{} new messages", external_messages.len()),
431	        );
432	        return;
433	    }
434	
435	    // Single message - show sender and preview
436	    let msg = external_messages[0];
437	
438	    // Get sender name
439	    let sender_name = member_info
440	        .member_info
441	        .iter()
442	        .find(|ami| ami.member_info.member_id == msg.message.author)
443	        .map(|ami| {
444	            match unseal_bytes_with_secrets(&ami.member_info.preferred_nickname, room_secrets) {
445	                Ok(bytes) => String::from_utf8_lossy(&bytes).to_string(),
446	                Err(_) => ami.member_info.preferred_nickname.to_string_lossy(),
447	            }
448	        })
449	        .unwrap_or_else(|| "Someone".to_string());
450	
451	    // Get message preview (decrypt if needed)
452	    let preview = get_message_preview(&msg.message.content, room_secrets);
453	
454	    show_notification(*room_key, &room_name, &sender_name, &preview);
455	}
456	
457	/// Extract a preview from message content, decrypting if necessary
458	fn get_message_preview(
459	    content: &RoomMessageBody,
460	    room_secrets: &std::collections::HashMap<u32, [u8; 32]>,
461	) -> String {
462	    use river_core::room_state::content::{
463	        ActionContentV1, EventContentV1, ReplyContentV1, TextContentV1, ACTION_TYPE_DELETE,
464	        ACTION_TYPE_EDIT, ACTION_TYPE_REACTION, ACTION_TYPE_REMOVE_REACTION, CONTENT_TYPE_ACTION,
465	        CONTENT_TYPE_EVENT, CONTENT_TYPE_REPLY, CONTENT_TYPE_TEXT, EVENT_TYPE_JOIN,
466	    };
467	
468	    let text = match content {
469	        RoomMessageBody::Public {
470	            content_type, data, ..
471	        } => match *content_type {
472	            CONTENT_TYPE_TEXT => TextContentV1::decode(data)
473	                .map(|t| t.text)
474	                .unwrap_or_else(|_| "[Failed to decode message]".to_string()),
475	            CONTENT_TYPE_ACTION => ActionContentV1::decode(data)
476	                .map(|action| match action.action_type {
477	                    ACTION_TYPE_EDIT => "[Edited a message]".to_string(),
478	                    ACTION_TYPE_DELETE => "[Deleted a message]".to_string(),
479	                    ACTION_TYPE_REACTION => action
480	                        .reaction_payload()
481	                        .map(|p| format!("Reacted with {}", p.emoji))
482	                        .unwrap_or_else(|| "[Reacted]".to_string()),
483	                    ACTION_TYPE_REMOVE_REACTION => "[Removed a reaction]".to_string(),
484	                    _ => "[Unknown action]".to_string(),
485	                })
486	                .unwrap_or_else(|_| "[Action]".to_string()),
487	            CONTENT_TYPE_REPLY => ReplyContentV1::decode(data)
488	                .map(|r| r.text)
489	                .unwrap_or_else(|_| "[Failed to decode reply]".to_string()),
490	            CONTENT_TYPE_EVENT => EventContentV1::decode(data)
491	                .map(|event| match event.event_type {
492	                    EVENT_TYPE_JOIN => "joined the room".to_string(),
493	                    _ => format!("[Event type {}]", event.event_type),
494	                })
495	                .unwrap_or_else(|_| "[Event]".to_string()),
496	            _ => "[Unknown message type]".to_string(),
497	        },
498	        RoomMessageBody::Private {
499	            content_type,
500	            ciphertext,
501	            nonce,
502	            secret_version,
503	            ..
504	        } => {
505	            // Look up the secret for this message's version
506	            if let Some(secret) = room_secrets.get(secret_version) {
507	                decrypt_with_symmetric_key(secret, ciphertext.as_slice(), nonce)
508	                    .map(|bytes| match *content_type {
509	                        CONTENT_TYPE_TEXT => TextContentV1::decode(&bytes)
510	                            .map(|t| t.text)
511	                            .unwrap_or_else(|_| String::from_utf8_lossy(&bytes).to_string()),
512	                        CONTENT_TYPE_REPLY => ReplyContentV1::decode(&bytes)
513	                            .map(|r| r.text)
514	                            .unwrap_or_else(|_| String::from_utf8_lossy(&bytes).to_string()),
515	                        CONTENT_TYPE_EVENT => EventContentV1::decode(&bytes)
516	                            .map(|event| match event.event_type {
517	                                EVENT_TYPE_JOIN => "joined the room".to_string(),
518	                                _ => format!("[Event type {}]", event.event_type),
519	                            })
520	                            .unwrap_or_else(|_| "[Event]".to_string()),
521	                        CONTENT_TYPE_ACTION => "[Action]".to_string(),
522	                        _ => String::from_utf8_lossy(&bytes).to_string(),
523	                    })
524	                    .unwrap_or_else(|_| "[Encrypted message]".to_string())
525	            } else {
526	                "[Encrypted message]".to_string()
527	            }
528	        }
529	    };
530	
531	    // Truncate to ~50 chars for notification (use truncate_str to avoid
532	    // panicking on multi-byte emoji at the boundary).
533	    if text.len() > 50 {
534	        format!("{}...", crate::util::truncate_str(&text, 47))
535	    } else {
536	        text
537	    }
538	}
539	
540	/// Mark a room as having completed initial sync
541	/// Should be called after first successful state load
542	pub fn mark_initial_sync_complete(room_key: &VerifyingKey) {
543	    INITIAL_SYNC_COMPLETE.write().insert(*room_key);
544	    info!(
545	        "Marked initial sync complete for room: {:?}",
546	        MemberId::from(*room_key)
547	    );
548	}
549

