pub use android::start_embedded_node;

/// Non-Android stub. The Android startup path in `App()` is itself
/// `cfg(target_os = "android")`-gated, so this stub is unreachable
/// in practice — but exposing it lets the module compile for host
/// `cargo check` / `cargo test` without dragging in freenet, tokio,
/// jni, or ndk-context.
#[cfg(not(target_os = "android"))]
#[allow(dead_code)]
pub fn start_embedded_node() {}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fallback_path_targets_known_package_id() {
        // The hardcoded fallback must point at the package id River
        // declares in `ui/Dioxus.toml` — if that identifier ever
        // changes, this constant has to follow or the bundled node
        // will write to a directory Android won't grant access to.
        assert!(
            FREENET_DATA_DIR_FALLBACK.contains("/org.freenet.river/"),
            "fallback {FREENET_DATA_DIR_FALLBACK} no longer targets org.freenet.river"
        );
        assert!(
            FREENET_DATA_DIR_FALLBACK.ends_with("/freenet"),
            "fallback {FREENET_DATA_DIR_FALLBACK} must end with /freenet \
             so the node has its own subdir under the app's private files area"
        );
    }

    /// On non-Android targets `android_files_dir` is the no-op stub,
    /// so `resolve_data_dir` MUST return the hardcoded fallback.
    /// Gated to non-android because on a real device the JNI lookup
    /// succeeds and returns a different (real) path — the assertion
    /// would not hold there.
    #[cfg(not(target_os = "android"))]
    #[test]
    fn resolve_data_dir_returns_fallback_off_device() {
        assert!(android_files_dir().is_none(), "host stub must return None");
        let dir = resolve_data_dir();
        assert_eq!(dir, PathBuf::from(FREENET_DATA_DIR_FALLBACK));
    }
}

/*
 * River MainActivity — extends the dx-generated WryActivity to start
 * RiverNodeService as a foreground service immediately on launch.
 *
 * Without this, Android's OOM killer can — and on Pixel-class devices
 * typically does — reap the process within seconds of the user
 * backgrounding the app, dropping every peer connection the embedded
 * Freenet node has built up. With the service running, the process is
 * categorised FOREGROUND_SERVICE for as long as the user keeps River
 * installed and the user hasn't tapped the "Stop" action.
 *
 * This file is part of the `ui/android/` overlay copied into
 * `target/dx/river-ui/.../kotlin/dev/dioxus/main/` by
 * `scripts/apply-android-overlay.sh`. It overwrites the empty
 * MainActivity stub dx generates. If dx regenerates the stub on a
 * fresh build, the overlay script re-applies on top.
 */
package dev.dioxus.main

import android.Manifest
import android.content.pm.PackageManager
import android.os.Build
import android.os.Bundle
import android.webkit.WebView
import androidx.core.app.ActivityCompat
import androidx.webkit.WebSettingsCompat
import androidx.webkit.WebViewFeature

// re-export buildconfig down from the parent (matches the dx stub)
import org.freenet.river.BuildConfig
typealias BuildConfig = BuildConfig

class MainActivity : WryActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        // POST_NOTIFICATIONS is a runtime permission on API 33+ — without
        // it the foreground-service notification is hidden, defeating
        // the "ongoing presence" UX. We ask once on first launch; if
        // denied, the FGS still runs but is invisible to the user (which
        // is fine — Android keeps the process alive either way).
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            val granted = ActivityCompat.checkSelfPermission(
                this,
                Manifest.permission.POST_NOTIFICATIONS,
            ) == PackageManager.PERMISSION_GRANTED
            if (!granted) {
                ActivityCompat.requestPermissions(
                    this,
                    arrayOf(Manifest.permission.POST_NOTIFICATIONS),
                    REQUEST_CODE_POST_NOTIFICATIONS,
                )
            }
        }

        RiverNodeService.start(this)
    }

    // Permit the WebView to report the system `prefers-color-scheme` to
    // the page. WITHOUT this, the WebView always reports `light`
    // regardless of the device's Dark theme setting, so our CSS
    // `@media (prefers-color-scheme: dark)` block in tailwind.css never
    // fires on Android. Pair with the `<meta name="color-scheme"
    // content="light dark">` Dioxus emits in App() — that meta tells the
    // WebView "this page handles both schemes," which suppresses
    // WebView's own algorithmic darkening so our CSS drives entirely.
    // Without the meta, enabling this would double-invert the page.
    override fun onWebViewCreate(webView: WebView) {
        super.onWebViewCreate(webView)
        // Permit the WebView to surface the system color scheme to the
        // page when our CSS declares it handles dark mode. Required pair
        // with `parent="@style/Theme.AppCompat.DayNight.NoActionBar"` in
        // `res/values/styles.xml` — without the DayNight theme, the
        // activity is locked light and the WebView's
        // `prefers-color-scheme` query never reports dark regardless of
        // this setting.
        if (WebViewFeature.isFeatureSupported(WebViewFeature.ALGORITHMIC_DARKENING)) {
            WebSettingsCompat.setAlgorithmicDarkeningAllowed(webView.settings, true)
        }
    }

    companion object {
        private const val REQUEST_CODE_POST_NOTIFICATIONS = 1001
    }
}

